function countIslands(grid) {
  const g = grid.map(row => [...row]), rows = g.length, cols = g[0].length //@init
  function sink(r, c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols || g[r][c] !== 1) return //@base
    g[r][c] = 2 //@mark
    sink(r + 1, c); sink(r - 1, c); sink(r, c + 1); sink(r, c - 1) //@recurse
  }
  let count = 0
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    if (g[r][c] !== 1) continue //@scan
    count++; sink(r, c) //@found
  }
  return count //@done
}

